using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Text;using System.Web.Script.Serialization;using XHLLauncher;
class FieldChecks {
 static int count;static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);count++;}
 static BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Main(string[] args){
  string fixture=Path.Combine(args[0],"field-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(fixture,"savegame","nested"));File.WriteAllText(Path.Combine(fixture,"enshrouded_server.json"),"{\"saveDirectory\":\"savegame\",\"logDirectory\":\"logs\"}");File.WriteAllText(Path.Combine(fixture,"savegame","nested","world.ksd"),"fixture");
  Check(FormatUtil.Bytes(1024)=="1.02 kB"&&FormatUtil.Megabytes(1073741824)=="1073.74 MB","Decimal file units and megabyte memory values are accurate");
  Check(RealmHistory.WorldFiles(fixture).Length==1,"Nested saves contribute to world metadata");
  using(var t=new TelemetryService(fixture,new LauncherSettings{ServerRoot=fixture,PublicIpLookup=false})){
   var parse=typeof(TelemetryService).GetMethod("ProcessLine",flags);Action<string,bool> line=(s,b)=>parse.Invoke(t,new object[]{s,b});
   line("[I 00:00:01,000] [online] Added peer 4(2) (steamid:123)",false);line("[I 00:00:01,001] [session] Add remote machine index 5",false);line("[server] Player 'Fixture' logged in",false);
   line("[I 00:00:02,000] m#5(test): up 1 down 2 remote 3 limit 4 lost 7, ping 0 ms, OperatingNormally",true);
   var all=(Dictionary<int,PlayerState>)typeof(TelemetryService).GetField("players",flags).GetValue(t);var player=all[4];
   Check(player.PingMs==0&&player.LostTotal==7,"Prefixed network log lines parse, including zero ping");Check(player.PingHistory.Count==0&&player.LastNetworkSample==DateTime.MinValue,"Historical samples never acquire a current measurement time");
   typeof(TelemetryService).GetField("processStarted",flags).SetValue(t,DateTime.Now.AddSeconds(-2));line("[I 00:00:02,000] m#5(test): up 1 down 2 remote 3 limit 4 lost 7, ping 0 ms, OperatingNormally",false);typeof(TelemetryService).GetMethod("PruneAndComputePlayerHealth",flags).Invoke(t,null);
   Check(player.PingHistory.Count==1&&player.PingMs==0&&player.OneMinuteAverage==0,"Recent zero ping participates in rolling statistics");Check(player.Jitter==-1,"Jitter requires two samples");
   player.LastNetworkSample=DateTime.Now.AddMinutes(-6);player.PingHistory.Clear();player.Jitter=50;player.OneMinuteAverage=999;typeof(TelemetryService).GetMethod("PruneAndComputePlayerHealth",flags).Invoke(t,null);
   Check(player.PingMs==-1&&player.HealthScore==-1&&player.OneMinuteAverage==-1&&player.FiveMinutePeak==-1&&player.Jitter==-1,"Stale samples clear connection estimates and rolling statistics");
   typeof(TelemetryService).GetField("lastInfoSuccess",flags).SetValue(t,DateTime.Now);typeof(TelemetryService).GetField("lastInfoCount",flags).SetValue(t,2);typeof(TelemetryService).GetField("lastRosterSuccess",flags).SetValue(t,DateTime.Now);typeof(TelemetryService).GetField("lastRosterCount",flags).SetValue(t,0);
   Check(t.PlayerCountText=="2"&&t.PlayerCountEvidence.Contains("differs"),"Named roster cannot silently overwrite contradictory server counts");
  }
  string backup=Path.Combine(fixture,"backup");Directory.CreateDirectory(backup);Check(BackupFacts.Describe(backup).StartsWith("Incomplete"),"Missing completion marker is not verified");File.WriteAllText(Path.Combine(backup,"VERIFIED.txt"),"fixture");Check(BackupFacts.Describe(backup).Contains("unavailable"),"Missing manifest cannot claim offline consistency");
  var js=new JavaScriptSerializer();var date=DateTime.UtcNow.AddDays(-3);File.WriteAllText(Path.Combine(backup,"manifest.json"),js.Serialize(new {CreatedUtc=date,ServerObservedRunning=true}));Check(BackupFacts.Describe(backup).Contains("Live copy")&&BackupFacts.Describe(backup).Contains("blocked"),"Live copy classification explains restore restriction");Check(Math.Abs((BackupFacts.Created(backup)-date).TotalSeconds)<1,"Backup date comes from manifest rather than copied-folder creation time");File.WriteAllText(Path.Combine(backup,"manifest.json"),js.Serialize(new {CreatedUtc=date,ServerObservedRunning=false}));Check(BackupFacts.Describe(backup).Contains("hashes checked at restore"),"Offline label does not imply a new hash verification");
  Check(ConfigurationDocument.FriendlyName("factoryProductionSpeedFactor").Contains("production time"),"Workshop label agrees with documented time semantics");
  if(args.Length>1){var data=Maintenance.Config(args[1]);var fields=ConfigurationDocument.Flatten(data);int problems=fields.Count(f=>ConfigurationDocument.FieldIssue(f)!=null);var report=new StringBuilder("# Saved server configuration field audit\n\nRead directly from the selected server configuration. These are saved settings; a running game's effective values are not exposed for every setting. Passwords and account lists are withheld. No gameplay values changed.\n\n| Field | Launcher label | Saved value | Editing status |\n|---|---|---|---|\n");foreach(var f in fields){bool secret=f.Key.ToLowerInvariant().Contains("password")||f.Path.StartsWith("bannedAccounts");string value=secret?"Withheld":js.Serialize(f.Value);report.AppendLine("| `"+f.Path+"` | "+f.Label+" | "+value.Replace("|","\\|")+" | "+(ConfigurationDocument.FieldIssue(f)??ConfigurationDocument.ReadOnlyReason(f)??"Supported editor")+" |");}report.AppendLine("\n"+fields.Count+" fields checked; "+problems+" values outside supported ranges require review. Saved values were preserved. Gameplay labels and common ranges were cross-checked against [Keen's gameplay settings documentation](https://enshrouded.zendesk.com/hc/en-us/articles/20453241249821-Server-Gameplay-Settings). The current build's flameLevelFogRemoval bound and all live effective values remain unverified by that article.");File.WriteAllText(Path.Combine(args[0],"Saved-configuration-fields.md"),report.ToString());Console.WriteLine("Saved configuration fields checked: "+fields.Count);
   var cfg=ConfigReader.Read(args[1]);try{var query=ServerQuery.Read("127.0.0.1",cfg.QueryPort,1500);Console.WriteLine("Live game query: "+query.Name+"; players="+query.Players+"; capacity="+query.Capacity);}catch(Exception ex){Console.WriteLine("Live query unavailable: "+ex.Message);}
  }
  Console.WriteLine(count+" field checks passed.");
 }
}
